from pathlib import Path
import json,re,hashlib,datetime
R=Path(__file__).parent
pages=json.loads((R/'pages.json').read_text())
issues=[]
def anchor(page,start,end=None):
 t=pages[page-1]['text']
 def pattern(s): return r'\s+(?:\d{3,4}\s+)?'.join(re.escape(w) for w in s.split())
 m=re.search(pattern(start),t)
 if m is None: raise ValueError(f'Page {page}: start not found: {start}')
 a=m.start()
 if end:
  e=re.search(pattern(end),t[m.end():])
  if e is None: raise ValueError(f'Page {page}: end not found: {end}')
  b=m.end()+e.end()
 else: b=m.end()
 return t[a:b]
